WITH base AS (SELECT id, country, city, rating, SUBSTRING(country, 1, 3) AS country_prefix, COALESCE(city, 'NONE') AS city_filled FROM suppliers WHERE city IS NOT NULL) SELECT CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, STDDEV_SAMP(rating) AS rating_stddev, COUNT(CASE WHEN country = 'UK' THEN 1 END) AS uk_count, COUNT_IF(city = 'Berlin') AS berlin_events, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count FROM base GROUP BY CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END
